"""Reproducible serial candidate checks, using the project runner's CPU/RSS guard."""
from pathlib import Path
import runpy,gc,json,hashlib
S=Path(__file__).resolve().parent;O=S.parent/'Functional register'
for name in ['check_functional_register.py','check_functional_contacts.py','check_functional_pin_seats.py','check_functional_transmission.py','check_functional_interfaces.py','check_functional_inherited_prints.py']:
 print('CHECK',name,flush=True);runpy.run_path(str(S/name),run_name='__main__');gc.collect()
h=hashlib.sha256((O/'geometry.npz').read_bytes()).hexdigest()
def read(n):
 d=json.load(open(O/n));assert d['geometry_sha256']==h,(n,'stale');return d
pr=read('Candidate manufacturing checks.json');co=read('Candidate contact checks.json');pi=read('Pin collar checks.json');tr=read('Transmission checks.json');it=read('Module interface checks.json');inh=read('Inherited manufacturing checks.json')
d=dict(status='DEVELOPMENT CHECKPOINT — NOT A PRINT RELEASE',task_complete=False,current_wall_design_replaced=False,geometry_sha256=h,implemented=['Master and slave mechanism cartridges with their own input clutch, storage clutch, lock, timing, power gearing, shafts and bearings','Three-piece timing assemblies and a removable four-pin timing link','Separate chassis with two horizontal friction pins and complete collar seats','Corrected carriage joining-pin through bores and collar seats, printing from the outer flat faces'],verified=dict(new_or_modified_print_parts=len(pr['parts']),new_parts_geometry_pass=pr['new_parts_print_pass'],sampled_motion_frames=co['sampled_frames'],solid_intersection_checks=co['checks'],new_part_collisions=co['collisions'],friction_pins=len(pi['pins']),collar_and_core_clearance_pass=pi['pin_clearance_pass'],external_gear_meshes=len(tr['meshes']),unit_ratio_pass=tr['unit_magnitude_pass'],fixed_external_phase_pass=tr['fixed_external_phase_pass'],joined_axle_ports_pass=it['port_pass']),inherited_parts_requiring_surface_review=[p['part'] for p in inh['parts'] if not p['print_geometry_pass']],unfinished=['WRITE/feedback cartridge and shared-controller connection','Resolve inherited working-surface print limitations; static fixture overhangs remain separately identified','40 mm elastic-band fit and preload across travel','Single-layout complete functional test and subsequent incremental layout-only pack'],limits=['Geometric checks only; no slicer or physical validation. Bambu Studio was not launched.','External gear speed checks concern steady-state magnitude, not reversal transients.','Current Wall register viewer remains unchanged.'])
(O/'Development status.json').write_text(json.dumps(d,indent=2));print(json.dumps(d['verified'],indent=2),flush=True)
